def get_scaled_eps_target(timesteps, schedule, gamma=5.0):
    sa = schedule["sqrt_alpha"][timesteps].view(-1, 1, 1, 1)
    sma = schedule["sqrt_one_minus_alpha"][timesteps].view(-1, 1, 1, 1)
    snr = (sa**2) / (sma**2)
    w = torch.clamp(gamma / snr, max=1.0)
    return torch.sqrt(w), sa, sma

def compute_training_target(x_0, noise, timesteps, schedule):
    scale, _, _ = get_scaled_eps_target(timesteps, schedule)
    return scale * noise

def predict_x0(model_output, x_t, timesteps, schedule):
    scale, sa, sma = get_scaled_eps_target(timesteps, schedule)
    eps_pred = model_output / scale.clamp(min=1e-8)
    return (x_t - sma * eps_pred) / sa.clamp(min=1e-8)
